import React from 'react';
import { createRoot } from 'react-dom/client';
import { Amplify } from 'aws-amplify';
import outputs from '../amplify_outputs.json';
import App from './App.jsx';
import './styles.css';

// Generated by `npx ampx sandbox` locally or by the Amplify Gen 2 build in CI.
// Do NOT invent a User Pool ID or put AWS access keys in the React source.
